// 1. Validate & Sanitize Input
const body = $json.body || $json;
const prompt = (body.prompt || body.message || '').trim();

if (!prompt) {
  throw new Error('Input validation failed: Prompt or message is required.');
}

const cropContext = (body.cropContext || body.crop || 'Wheat').trim();
const state = (body.state || (body.location && body.location.state) || 'Haryana').trim();
const district = (body.district || (body.location && body.location.district) || 'Karnal').trim();
const language = body.language === 'hi' ? 'hi' : 'en';
const files = Array.isArray(body.files) ? body.files : [];

return [{
  json: {
    validatedPrompt: prompt,
    cropContext,
    location: { state, district },
    language,
    files,
    receivedAt: new Date().toISOString()
  }
}];

// 2. Understand User Intent & Extract Entities
const input = $json;
const p = input.validatedPrompt.toLowerCase();

// Intent Detection Flags
const isCrop = /yellow|पीला|leaf|पत्ती|disease|रोग|rust|रतुआ|blight|झुलसा|pest|कीड़ा|spot|धब्बा|symptom|chlorosis/.test(p);
const isWeather = /weather|मौसम|rain|बारिश|spray|छिड़काव|wind|हवा|forecast|पूर्वानुमान|temp|तापमान|cloud|बादल/.test(p);
const isMandi = /mandi|मंडी|price|भाव|profit|मुनाफा|sell|बेचना|quintal|क्विंटल|cost|खर्च|लागत|revenue|कमाई/.test(p);
const isSoil = /soil|मिट्टी|khad|खाद|fertilizer|urea|यूरिया|dap|ph|saline|alkaline|organic carbon|npk/.test(p);
const isSchemes = /scheme|योजना|pmfby|बीमा|claim|क्लेम|loss|नुकसान|hailstorm|ओलावृष्टि|subsidy|मुआवजा/.test(p);

// Determine tool strategy: Multi-Tool or Single-Tool
const toolMatchCount = [isCrop, isWeather, isMandi, isSoil, isSchemes].filter(Boolean).length;
let intent = 'orchestrate';

if (toolMatchCount > 1) {
  intent = 'orchestrate';
} else if (isMandi) {
  intent = 'mandi';
} else if (isCrop) {
  intent = 'crop_health';
} else if (isWeather) {
  intent = 'weather';
} else if (isSoil) {
  intent = 'soil';
} else if (isSchemes) {
  intent = 'schemes';
}

// Extract Mandi Quantities, Prices, and Costs
let quantity = 50;
const qMatch = p.match(/(\d+(?:\.\d+)?)\s*(?:quintals?|qtl|क्विंटल)/);
if (qMatch) quantity = parseFloat(qMatch[1]);

let price = 2450;
const pMatch = p.match(/(?:rs\.?|inr|₹|भाव|दर|रेट|at)\s*[:=]?\s*(\d{3,5})/);
if (pMatch) {
  price = parseFloat(pMatch[1]);
} else {
  const pMatch2 = p.match(/(\d{3,5})\s*(?:rs|inr|₹|per\s*qtl|\/qtl|रुपये)/);
  if (pMatch2) price = parseFloat(pMatch2[1]);
}

// Extract Total Costs (Test C: total costs are ₹20,000)
let totalCosts = null;
const totCostMatch = p.match(/(?:total\s+costs?|total\s+expenses?|costs?|expenses?|कुल\s*खर्च|लागत)\s*(?:are|is|of|=|:)?\s*(?:rs\.?|inr|₹)?\s*(\d+(?:,\d+)?(?:\.\d+)?)/);
if (totCostMatch) {
  totalCosts = parseFloat(totCostMatch[1].replace(/,/g, ''));
}

let transport = 30;
let loading = 15;
let lumpSum = 0;
let cess = 1.0;

if (totalCosts !== null) {
  lumpSum = totalCosts;
  transport = 0;
  loading = 0;
  cess = 0;
}

return [{
  json: {
    ...input,
    intent,
    extracted: {
      crop: input.cropContext,
      quantity,
      price,
      lumpSumCost: lumpSum,
      transportCost: transport,
      loadingCost: loading,
      cessPercent: cess
    }
  }
}];

